    int n;
    scanf("%d", &n);

    int a[10][10];
    int zr = -1, zc = -1;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%d", &a[i][j]);
            if (a[i][j] == 0) {
                zr = i;
                zc = j;
            }
        }
    }

    int fullRow = (zr == 0) ? 1 : 0;
    int magicSum = 0;

    for (int j = 0; j < n; j++) {
        magicSum += a[fullRow][j];
    }

    int missingRowSum = 0;
    for (int j = 0; j < n; j++) {
        missingRowSum += a[zr][j];
    }

    int missingValue = magicSum - missingRowSum;

    printf("%d\n%d\n%d\n", missingValue, zr + 1, zc + 1);

    return 0;
}
